<?php
$popularLimit=!empty($popularAdmin)?100:10;
$popular=$conn->query('SELECT k.id,k.judul,COUNT(nv.id) AS views FROM naskah_views nv JOIN katalog k ON k.id=nv.id_naskah GROUP BY k.id,k.judul ORDER BY views DESC,k.id DESC LIMIT '.$popularLimit); ?>
<section class="card w-100 h-100 shadow-sm p-3 mb-4 popular-manuscripts"><h3 class="h5 fw-bold"><i class="fa-solid fa-eye me-2" aria-hidden="true"></i>Naskah Terpopuler<?= empty($popularAdmin)?' — 10 teratas':'' ?></h3><div class="table-responsive <?= !empty($popularAdmin)?'admin-scroll-table':'' ?>" <?= !empty($popularAdmin)?'data-visible-rows="10" tabindex="0" role="region" aria-label="Daftar naskah terpopuler hingga 100 data"':'' ?>><table class="table table-sm mb-0"><thead><tr><th>No.</th><th>Naskah</th><th class="text-end">Kunjungan</th></tr></thead><tbody>
<?php $rank=0;while($popularRow=$popular->fetch_assoc()): ?><tr><td><?= ++$rank ?></td><td><a href="<?= BASE_URL ?>/detail.php?id=<?= (int)$popularRow['id'] ?>"><?= htmlspecialchars($popularRow['judul'],ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8') ?></a></td><td class="text-end"><?= number_format((int)$popularRow['views']) ?></td></tr><?php endwhile;if(!$rank): ?><tr><td colspan="3">Belum ada kunjungan naskah.</td></tr><?php endif; ?></tbody></table></div></section>
